        .I1(mOutPtr[0]),
        .I2(\mOutPtr_reg[2]_0 ),
        .I3(fit_U0_ap_start),
        .I4(Q[1]),
        .I5(mOutPtr[2]),
        .O(\mOutPtr[2]_i_1_n_2 ));
  FDRE \mOutPtr_reg[0] 
       (.C(ap_clk),
        .CE(1'b1),
        .D(\mOutPtr[0]_i_1_n_2 ),
        .Q(mOutPtr[0]),
        .R(empty_n_reg_1));
  FDRE \mOutPtr_reg[1] 
       (.C(ap_clk),
        .CE(1'b1),
        .D(\mOutPtr[1]_i_1_n_2 ),
        .Q(mOutPtr[1]),
        .R(empty_n_reg_1));
  FDRE \mOutPtr_reg[2] 
       (.C(ap_clk),
        .CE(1'b1),
        .D(\mOutPtr[2]_i_1_n_2 ),
        .Q(mOutPtr[2]),
        .R(empty_n_reg_1));
endmodule
`ifndef GLBL
`define GLBL
